import { test, expect } from '@playwright/test';

test.describe('Notification Auto-Dismissal', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should auto-dismiss notification after 5 seconds', async ({ page }) => {
    // Intercept the API call to fetch notifications
    await page.route('**/api/notifications', (route) => {
      route.continue();
    });

    // Get the notification button using getByRole
    const notificationButton = page.getByRole('button', { name: /new notification/i });
    await expect(notificationButton).toBeVisible();

    // Click the notification button to open the notification
    await notificationButton.click();

    // Wait for the notification to appear
    const notification = page.getByRole('region', { name: /notification/i });
    await expect(notification).toBeVisible();

    // Get the dismiss button using getByRole
    const dismissButton = page.getByRole('button', { name: /dismiss/i });
    await expect(dismissButton).toBeVisible();

    // Verify the notification content is displayed
    const notificationContent = page.getByText(/new notification/i);
    await expect(notificationContent).toBeVisible();

    // Wait for 5 seconds
    await page.waitForTimeout(5000);

    // Verify the notification is dismissed
    await expect(notification).not.toBeVisible();

    // Verify the dismiss button is no longer visible
    await expect(dismissButton).not.toBeVisible();

    // Verify the notification count is updated
    const notificationCount = page.getByText(/3 notifications/i);
    await expect(notificationCount).toBeVisible();

    // Verify the notification count is correct
    const count = page.getByText(/3 notifications/i);
    const countValue = await count.evaluate((el) => parseInt(el.textContent.match(/(\d+)/i)[1]));
    expect(countValue).toBe(3);
  });

  test('should not dismiss notification if dismiss button is disabled', async ({ page }) => {
    // Intercept the API call to fetch notifications
    await page.route('**/api/notifications', (route) => {
      route.continue();
    });

    // Get the notification button using getByRole
    const notificationButton = page.getByRole('button', { name: /new notification/i });
    await expect(notificationButton).toBeVisible();

    // Click the notification button to open the notification
    await notificationButton.click();

    // Wait for the notification to appear
    const notification = page.getByRole('region', { name: /notification/i });
    await expect(notification).toBeVisible();

    // Get the dismiss button using getByRole
    const dismissButton = page.getByRole('button', { name: /dismiss/i });
    await expect(dismissButton).toBeVisible();

    // Verify the notification content is displayed
    const notificationContent = page.getByText(/new notification/i);
    await expect(notificationContent).toBeVisible();

    // Wait for 5 seconds
    await page.waitForTimeout(5000);

    // Verify the notification is still visible
    await expect(notification).toBeVisible();

    // Verify the dismiss button is still visible
    await expect(dismissButton).toBeVisible();

    // Verify the notification count is still correct
    const count = page.getByText(/3 notifications/i);
    const countValue = await count.evaluate((el) => parseInt(el.textContent.match(/(\d+)/i)[1]));
    expect(countValue).toBe(3);

    // Verify the dismiss button is not disabled
    const buttonDisabled = page.getByRole('button', { name: /dismiss/i, disabled: true });
    await expect(buttonDisabled).not.toBeVisible();
  });
});
